      const hubTown = distObj.hubs[Math.floor(generatedCount / ap26DistrictsInfo.length) % distObj.hubs.length];
      const prefix = regionalCollegePrefixes[generatedCount % regionalCollegePrefixes.length];
      const suffix = regionalCollegeSuffixes[Math.floor(generatedCount / 7) % regionalCollegeSuffixes.length];
      const serialNum = currentApCetCount + 1;
      const codeStr = `${distObj.codePrefix}${String((generatedCount % 89) + 11)}`;

      const tierStep = generatedCount % 6;
      let baseCse = 32000 + (generatedCount * 580) + (tierStep * 8500);
      if (baseCse > 235000) baseCse = 145000 + ((generatedCount * 1300) % 165000);

      const isLowPlacement = baseCse > 68000;
      const numRate = isLowPlacement ? (35 + (generatedCount % 13)) : (52 + (generatedCount % 16));
      const medPkg = isLowPlacement ? +(3.0 + (generatedCount % 5) * 0.1).toFixed(1) : +(3.6 + (generatedCount % 7) * 0.15).toFixed(1);
      const avgPkg = +(medPkg + 0.5).toFixed(1);
      const highPkg = isLowPlacement ? +(7.0 + (generatedCount % 5) * 0.8).toFixed(1) : +(11.0 + (generatedCount % 7) * 1.2).toFixed(1);
      const starNum = isLowPlacement ? (2.9 + (generatedCount % 6) * 0.1).toFixed(1) : (3.6 + (generatedCount % 6) * 0.1).toFixed(1);
      const gradeStr = isLowPlacement ? (starNum >= 3.2 ? "B" : "B-") : (starNum >= 3.9 ? "A" : "B+");
