    window.getCollegeImages = function(college) {
      if (!college) return [campusPhotoPool[0]];
      let images = [];
      if (Array.isArray(college.images) && college.images.length > 0) {
        images = college.images;
      } else if (typeof collegeRealImagesMap !== "undefined") {
        if (college.id && collegeRealImagesMap[college.id]) images = collegeRealImagesMap[college.id];
        else if (college.code && collegeRealImagesMap[college.code]) images = collegeRealImagesMap[college.code];
        else {
          const cid = (college.id || "").toLowerCase();
          const code = (college.code || "").toUpperCase();
          if (collegeRealImagesMap[cid]) images = collegeRealImagesMap[cid];
          else if (collegeRealImagesMap[code]) images = collegeRealImagesMap[code];
        }
      }
      if ((!images || images.length === 0) && college.imageUrl && typeof college.imageUrl === "string") {
        images = [college.imageUrl];
      }
      if (!images || images.length === 0) {
        images = [campusPhotoPool[0]];
      }

      // Route /college_images appropriately:
      // When opened in a browser over HTTP/HTTPS, use relative URL so images are served directly by the host!
      // When opened offline as file:///, prefix with publicHost so cloud images can be fetched.
      const publicHost = (window.I2T_CONFIG && window.I2T_CONFIG.IMAGE_CDN) ? window.I2T_CONFIG.IMAGE_CDN : "";
      return images.map(img => {
        if (typeof img === "string" && img.startsWith("/college_images/")) {
          if (typeof window !== "undefined" && window.location && window.location.protocol === "file:" && publicHost) {
            return publicHost + img;
          }
          return img;
        }
        return img;
      });
    };

    window.getCollegeImageUrl = function(college) {
      if (!college) return campusPhotoPool[0];
      if (typeof window.getCollegeImages === "function") {
        const list = window.getCollegeImages(college);
        if (Array.isArray(list) && list.length > 0) return list[0];
      }
      if (college.imageUrl && typeof college.imageUrl === "string") {
        const publicHost = (window.I2T_CONFIG && window.I2T_CONFIG.IMAGE_CDN) ? window.I2T_CONFIG.IMAGE_CDN : "";
        if (college.imageUrl.startsWith("/college_images/") && typeof window !== "undefined" && window.location && window.location.protocol === "file:" && publicHost) {
          return publicHost + college.imageUrl;
        }
        return college.imageUrl;
      }

      if (!college) return campusPhotoPool[0];
      const cid = (college.id || "").toLowerCase();
      const code = (college.code || "").toLowerCase();
      const name = (college.name || "").toLowerCase();

      if (collegeImageMap[cid]) return collegeImageMap[cid];
      if (collegeImageMap[code]) return collegeImageMap[code];

      for (const [key, url] of Object.entries(collegeImageMap)) {
        if (cid.includes(key) || code.includes(key) || name.includes(key)) {
          return url;
        }
      }

      let hash = 0;
      const str = cid || code || name || "col";
      for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) - hash) + str.charCodeAt(i);
        hash |= 0;
      }
      const idx = Math.abs(hash) % campusPhotoPool.length;
      return campusPhotoPool[idx];
    };

    window.handleCollegeImgError = function(imgEl, codeOrId) {
      if (!imgEl) return;
      const currentStep = parseInt(imgEl.dataset.fallbackStep || "0", 10);
      const origSrc = imgEl.dataset.origSrc || imgEl.getAttribute("src") || "";
      const tunnelHost = (window.I2T_CONFIG && window.I2T_CONFIG.IMAGE_CDN)
        ? window.I2T_CONFIG.IMAGE_CDN
        : "https://shirt-advisors-county-labour.trycloudflare.com";

      if (currentStep === 0) {
        imgEl.dataset.fallbackStep = "1";
        if (origSrc.startsWith("/college_images/")) {
          imgEl.src = "/public" + origSrc;
          return;
        } else if (origSrc.startsWith("/public/college_images/")) {
          imgEl.src = origSrc.replace(/^\/public/, "");
          return;
        }
      }

      if (currentStep <= 1) {
        imgEl.dataset.fallbackStep = "2";
        let relPath = origSrc;
        if (relPath.startsWith("http://") || relPath.startsWith("https://")) {
          try {
            const u = new URL(relPath);
            relPath = u.pathname;
          } catch(e) {}
        }
        if (relPath.includes("college_images")) {
          const match = relPath.match(/\/college_images\/.+$/);
          if (match) {
            imgEl.src = tunnelHost.replace(/\/$/, "") + match[0];
            return;
          }
        }
      }

      // Step 3: High-quality college architectural photo from pool
      imgEl.dataset.fallbackStep = "3";
      imgEl.onerror = null;
      const key = (codeOrId || "ENG").toString().toUpperCase();
      let hash = 0;
      for (let i = 0; i < key.length; i++) {
        hash = ((hash << 5) - hash) + key.charCodeAt(i);
        hash |= 0;
      }
      const pool = (typeof campusPhotoPool !== "undefined" && Array.isArray(campusPhotoPool) && campusPhotoPool.length > 0)
        ? campusPhotoPool
        : ["https://images.unsplash.com/photo-1541339907198-e08756dedf3f?w=800&auto=format&fit=crop&q=80"];
      const poolIdx = Math.abs(hash) % pool.length;
      imgEl.src = pool[poolIdx];
    };

    // =========================================================================